ormation. The authorization middleware checks if the requesting user has permission to access the target user, but the check can be bypassed when requesting non-existent user IDs.\",\n            \"context\": {\n                \"code_snippet\": \"user = db.query('SELECT * FROM users WHERE id = ?', target_id); if user: check_permission(requester, user)\",\n                \"api_calls_per_day\": 5000000,\n                \"sensitive_data_types\": [\"email\", \"phone\", \"address\", \"purchase_history\"],\n                \"compliance_requirements\": [\"GDPR\", \"CCPA\", \"SOC2\"]\n            },\n            \"constraints\": [\"Must maintain API response time under 200ms\", \"Cannot break existing API contracts\", \"Must add audit logging\"],\n            \"stakeholders\": [\"Security Team\", \"API Team\", \"Compliance\", \"Product Team\"]\n        }\n    ]\n    \n    selected = scenarios[seed % len(scenarios)]\n    \n    # Add deterministic adversarial elements\n    adversarial_elements = [\n        \"The proposed solution must not rely on any third-party security libraries that were introduced after 2020-01-01\",\n        \"Consider that an attacker has already discovered the vulnerability and may be actively exploiting it\",\n        \"The solution must account for legacy systems that cannot be immediately patched\",\n        \"Budget constraints limit the solution to internal resources only (no external consultants)\",\n        \"The fix must be deployable without downtime during business hours (9 AM - 6 PM EST)\"\n    ]\n    \n    selected[\"adversarial_elements\"] = adversarial_elements[:2 + (seed % 3)]\n    \n    return selected\n\nif __name__ == \"__main__\":\n    input_data = generate_input(42)\n    print(json.dumps(input_data, indent=2))\n",
